-- 20260814_backfill_sankhya_checklists.sql
-- Modelos extraídos de Checklist_Minucioso_Entregas_Sankhya.xlsx.
-- Preenche tarefas faltantes das obrigações já cadastradas, por nome, sem
-- apagar nem sobrescrever itens personalizados pela equipe.

with sankhya_template(obligation_name, position, description) as (
  values
  ('Alvaras licencas e registros de funcionamento / bombeiros e orgaos anuentes', 0, 'Planejamento — Confirmar aplicabilidade, empresa, competência, prazo legal e prazo interno: Revisar cadastro da empresa, regime, IE/IM, estabelecimento, eventos do período e agenda oficial. Confirmar se Alvaras licencas e registros de funcionamento / bombeiros e orgaos anuentes é original, retificadora, sem movimento ou não aplicável.'),
  ('Alvaras licencas e registros de funcionamento / bombeiros e orgaos anuentes', 1, 'Acessos — Validar certificado, procuração, perfil e versão dos sistemas: Testar login antes do fechamento; conferir validade do certificado, procurações, permissões Sankhya e versão do validador/leiaute. Não iniciar transmissão com acesso pendente.'),
  ('Alvaras licencas e registros de funcionamento / bombeiros e orgaos anuentes', 2, 'Corte — Executar corte documental e validar completude: Cobrar documentos faltantes; encerrar interfaces; verificar cancelamentos, devoluções, notas extemporâneas e lançamentos após o corte; registrar exceções.'),
  ('Alvaras licencas e registros de funcionamento / bombeiros e orgaos anuentes', 3, 'Extração Sankhya — Extrair bases do Sankhya com filtros documentados: Usar Contabilidade > Razão, Balancete e Demonstrativos; Repositório de Arquivos (2.316); Cadastro de Empresas (2.44). Registros em Junta/órgão competente ficam fora do ERP. Registrar empresa, período, filtros, data/hora e usuário; salvar arquivos sem edição como base bruta.'),
  ('Alvaras licencas e registros de funcionamento / bombeiros e orgaos anuentes', 4, 'Cadastro — Revisar cadastros mestres que determinam a entrega: Amostrar e validar CNPJ/CPF, IE, município, NCM, CEST, CFOP, CST/CSOSN, TOP, natureza, centro de resultado, contas, regras de retenção e alíquotas aplicáveis.'),
