  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 3, 'Extração Sankhya — Extrair bases do Sankhya com filtros documentados: Usar Central - Compras/Vendas/Mov. Internas (2.158); cadastro de Impostos (2.188); retenções e Integração Impostos (3.10). Fechamento/consulta no Portal Web EFD-Reinf/e-CAC ou integração contratada. Registrar empresa, período, filtros, data/hora e usuário; salvar arquivos sem edição como base bruta.'),
  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 4, 'Cadastro — Revisar cadastros mestres que determinam a entrega: Amostrar e validar CNPJ/CPF, IE, município, NCM, CEST, CFOP, CST/CSOSN, TOP, natureza, centro de resultado, contas, regras de retenção e alíquotas aplicáveis.'),
  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 5, 'Excel — Executar análise independente no Excel: Base por CNPJ beneficiário, natureza do rendimento e evento; remover duplicidades; somar retenções; cruzar notas/pagamentos/razão x totalizadores da Reinf e DCTFWeb.'),
  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 6, 'Conciliação — Conciliar fontes independentes e o razão contábil: Amarrar total operacional/fiscal/financeiro com razão, guias, declarações anteriores e saldos transportados. Investigar sinais invertidos, duplicidade e diferença de período.'),
  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 7, 'Geração — Gerar arquivo, memória, guia ou relatório sem ajustes manuais ocultos: Corrigir erros na origem no Sankhya; regerar após cada ajuste; manter versão, hash/nome do arquivo e log das alterações. Ajuste manual exige memória e aprovação.'),
  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 8, 'Validador — Importar e validar no ambiente oficial/aplicável: Portal Web EFD-Reinf/e-CAC ou WebService; consultar retorno de cada evento, fechamento e totalizadores: https://www.gov.br/receitafederal/pt-br/acesso-a-informacao/perguntas-frequentes/sped/efd-reinf/efdr'),
  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 9, 'Revisão — Aplicar revisão técnica por segunda pessoa: Revisor refaz amostra dos cálculos, confere empresa/período, totais, códigos, vencimento e dados bancários; compara versão final com a revisada.'),
  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 10, 'Entrega — Transmitir, protocolar ou liberar pagamento: Transmitir somente a versão aprovada; verificar retorno de processamento e status final. Para guia, conferir CNPJ, PA, código, valor e vencimento antes de agendar.'),
  ('EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais', 11, 'Pós-entrega — Confirmar efeitos e arquivar dossiê completo: Consultar processamento, pendências e conta fiscal; conferir reflexo contábil/financeiro; salvar arquivo transmitido, recibo, memória, Excel, guia, comprovante e aprovação por empresa/ano/competência.')
)
insert into checklist_items (obligation_id, description, position)
select o.id, t.description, t.position
from obligations o
join sankhya_template t
  on lower(trim(o.name)) = lower(trim(t.obligation_name))
where not exists (
  select 1
  from checklist_items ci
  where ci.obligation_id = o.id
    and lower(trim(ci.description)) = lower(trim(t.description))
);
